        ('/**\n     * Returns set instance by name.\n     * \n     * @param <V> type of value\n     * @param name - name of object\n     * @return Set object\n     */', '/**\n     * Returns set instance by name.\n     * \n     * @param <V> type of value\n     * @param name 对象名称\n     * @return Set object\n     */'),
